import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    static final long INF = (long) 4e18;

    // 计算一个长度为L的连续段中，减少x个字符的最小代价
    static long[] calcRunCost(int L, long[] a) {
        // f[i][j]：前i个字符，恰好减少j个字符的最小代价
        long[][] f = new long[L + 1][L];
        for (int i = 0; i <= L; i++) {
            for (int j = 0; j < L; j++) {
                f[i][j] = INF;
            }
        }
        f[0][0] = 0;

        for (int i = 0; i < L; i++) {
            for (int j = 0; j < L; j++) {
                if (f[i][j] == INF) {
                    continue;
                }

                // 不压缩当前位置
                if (f[i + 1][j] > f[i][j]) {
                    f[i + 1][j] = f[i][j];
                }

                // 从当前位置开始压缩长度为k的一段
                for (int k = 2; k <= L - i; k++) {
                    int nj = j + k - 1;
                    long cost = f[i][j] + a[k];
                    if (f[i + k][nj] > cost) {
                        f[i + k][nj] = cost;
                    }
                }
            }
        }

        long[] res = new long[L];
        for (int j = 0; j < L; j++) {
            res[j] = f[L][j];
        }
        return res;
    }

    // 求解单组测试
    static long solveCase(int n, int m, String s, long[] a) {
        int need = n - m;

        // 拆分连续段
        int[] runs = new int[n];
        int runCount = 0;
        int cnt = 1;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                cnt++;
            } else {
                runs[runCount++] = cnt;
                cnt = 1;
            }
        }
        runs[runCount++] = cnt;

        // 分组背包
        long[] dp = new long[need + 1];
        for (int i = 0; i <= need; i++) {
            dp[i] = INF;
        }
        dp[0] = 0;

        for (int idx = 0; idx < runCount; idx++) {
            int L = runs[idx];
            long[] costRun = calcRunCost(L, a);
            long[] ndp = new long[need + 1];
            for (int i = 0; i <= need; i++) {
                ndp[i] = INF;
            }

            for (int old = 0; old <= need; old++) {
                if (dp[old] == INF) {
                    continue;
                }
                int maxDec = Math.min(L - 1, need - old);
                for (int dec = 0; dec <= maxDec; dec++) {
                    if (costRun[dec] == INF) {
                        continue;
                    }
                    long val = dp[old] + costRun[dec];
                    if (ndp[old + dec] > val) {
                        ndp[old + dec] = val;
                    }
                }
            }
            dp = ndp;
        }

        return dp[need] == INF ? -1 : dp[need];
    }

    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader();
        StringBuilder sb = new StringBuilder();

        int T = fr.nextInt();
        while (T-- > 0) {
            int n = fr.nextInt();
            int m = fr.nextInt();
            String s = fr.next();
            long[] a = new long[n + 1];
            for (int i = 1; i <= n; i++) {
                a[i] = fr.nextLong();
            }

            long ans = solveCase(n, m, s, a);
            sb.append(ans).append('\n');
        }

        System.out.print(sb.toString());
    }

    // 默认不用快读，这里用较常规的BufferedReader + StringTokenizer
    static class FastReader {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}
